-- Phase 2 — cashier («تصمیم پشت صندوق»), partner discounts, recurring delivery lists.
-- Money is integer minor units (Rial). Rates are basis points (100 bps = 1%).
-- Admin-editable stacking order and caps for the cashier engine.
-- Line-level steps (price_selection, partner_discount, recurring_*) run in step_order;
-- order-level payment steps (coins, credit) always run after every line-level step.
    -- price_selection: lowest | contract_first ; discounts: stack ; payments: payment ; guard: guard
CREATE TABLE IF NOT EXISTS cashier_rules (
    id           BIGSERIAL PRIMARY KEY,
    rule_key     TEXT    NOT NULL UNIQUE,
    step_order   INTEGER NOT NULL CHECK (step_order BETWEEN 1 AND 999),
    enabled      INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    mode         TEXT    NOT NULL CHECK (mode IN ('lowest', 'contract_first', 'stack', 'payment', 'guard')),
    percent_bps  INTEGER CHECK (percent_bps IS NULL OR percent_bps BETWEEN 0 AND 10000),
    cap_bps      INTEGER CHECK (cap_bps IS NULL OR cap_bps BETWEEN 0 AND 10000),
    cap_scope    TEXT    NOT NULL DEFAULT 'line' CHECK (cap_scope IN ('line', 'order')),
    min_items    INTEGER CHECK (min_items IS NULL OR min_items >= 1),
    funded_by    TEXT    CHECK (funded_by IS NULL OR funded_by IN ('platform', 'seller', 'partner')),
    note         TEXT,
    updated_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at   TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at   TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

