-- Partner discounts (گیفت‌آسان، شادشهر، پادویرا، ...). Auto-applied when coupon_code is NULL.
CREATE TABLE IF NOT EXISTS partner_discounts (
    id                  BIGSERIAL PRIMARY KEY,
    title_fa            TEXT    NOT NULL,
    partner_supplier_id INTEGER REFERENCES suppliers(id) ON DELETE SET NULL,
    partner_name        TEXT,
    scope               TEXT    NOT NULL CHECK (scope IN ('all', 'category', 'product', 'seller')),
    category_id         INTEGER REFERENCES categories(id) ON DELETE CASCADE,
    product_id          INTEGER REFERENCES products(id) ON DELETE CASCADE,
    seller_supplier_id  INTEGER REFERENCES suppliers(id) ON DELETE CASCADE,
    channel             TEXT    NOT NULL DEFAULT 'any' CHECK (channel IN ('any', 'retail', 'organization')),
    percent_bps         INTEGER NOT NULL CHECK (percent_bps BETWEEN 1 AND 10000),
    max_discount_minor BIGINT CHECK (max_discount_minor IS NULL OR max_discount_minor > 0),
    valid_from          TEXT,
    valid_until         TEXT,
    funded_by           TEXT    NOT NULL DEFAULT 'partner' CHECK (funded_by IN ('partner', 'platform')),
    coupon_code         TEXT,
    status              TEXT    NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'archived')),
    created_by_user_id  INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at          TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    CHECK (partner_supplier_id IS NOT NULL OR partner_name IS NOT NULL),
    CHECK (scope <> 'category' OR category_id IS NOT NULL),
    CHECK (scope <> 'product' OR product_id IS NOT NULL),
    CHECK (scope <> 'seller' OR seller_supplier_id IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS ix_partner_discounts_status ON partner_discounts(status, scope);

CREATE UNIQUE INDEX IF NOT EXISTS ux_partner_discounts_coupon ON partner_discounts(coupon_code);

-- Recurring delivery (Subscribe & Save) for restaurants and offices.
-- A due run only produces a quote for the buyer to confirm; money is never charged automatically.
CREATE TABLE IF NOT EXISTS recurring_lists (
    id               BIGSERIAL PRIMARY KEY,
    user_id          INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    organization_id  INTEGER REFERENCES organizations(id) ON DELETE SET NULL,
    title            TEXT    NOT NULL,
    frequency        TEXT    NOT NULL CHECK (frequency IN ('weekly', 'biweekly', 'monthly')),
    next_run_on      TEXT    NOT NULL,
    status           TEXT    NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'paused', 'cancelled')),
    last_run_on      TEXT,
    created_at       TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    updated_at       TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE INDEX IF NOT EXISTS ix_recurring_lists_user ON recurring_lists(user_id, status);

CREATE INDEX IF NOT EXISTS ix_recurring_lists_due ON recurring_lists(status, next_run_on);

CREATE TABLE IF NOT EXISTS recurring_list_items (
    id          BIGSERIAL PRIMARY KEY,
    list_id     INTEGER NOT NULL REFERENCES recurring_lists(id) ON DELETE CASCADE,
    product_id  INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    offer_id    INTEGER REFERENCES seller_offers(id) ON DELETE SET NULL,
    quantity    INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 100000),
    UNIQUE (list_id, product_id)
);

CREATE TABLE IF NOT EXISTS recurring_runs (
    id             BIGSERIAL PRIMARY KEY,
    list_id        INTEGER NOT NULL REFERENCES recurring_lists(id) ON DELETE CASCADE,
    scheduled_for  TEXT    NOT NULL,
    status         TEXT    NOT NULL CHECK (status IN ('quoted', 'failed', 'confirmed', 'skipped')),
    payable_minor BIGINT,
    quote_json     TEXT,
    error          TEXT,
    created_at     TEXT    NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    UNIQUE (list_id, scheduled_for)
);
